describe('Login Page - Password Validation', () => {
  it('should not change the URL when the password is incorrect', () => {
    cy.visit('https://the-internet.herokuapp.com/login');
    cy.get('#username').type('tomsmith');
    cy.get('#password').type('wrongpassword');
    cy.get('button[type="submit"]').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/login');
    cy.get('.flash.error').should('contain', 'Your password is invalid!');
  });

  it('should not change the URL when the username is incorrect', () => {
    cy.visit('https://the-internet.herokuapp.com/login');
    cy.get('#username').type('wronguser');
    cy.get('#password').type('wrongpassword');
    cy.get('button[type="submit"]').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/login');
    cy.get('.flash.error').should('contain', 'Your password is invalid!');
  });
});
